1768. 交替合并字符串
1768. 交替合并字符串 - 力扣（LeetCode）
[!Note]
​	给你两个字符串 word1 和 word2 。请你从 word1 开始，通过交替添加字母来合并字符串。如果一个字符串比另一个字符串长，就将多出来的字母追加到合并后字符串的末尾。
​	返回 合并后的字符串 。
public class Solution {
    public string MergeAlternately(string word1, string word2) {
        string ans = "";
        int n = word1.Length >= word2.Length ? word1.Length : word2.Length;  // 取最大值
        for(int i = 0; i < n; i++) {
            // 交替合并，如果没到字符串尾就继续添加
            if(i < word1.Length)
                ans += word1[i];
            if(i < word2.Length)
                ans += word2[i];
        }

        return ans;
    }
}
​	官方解：
public class Solution {
    public string MergeAlternately(string word1, string word2) {
        int m = word1.Length, n = word2.Length;
        int i = 0, j = 0;

        StringBuilder ans = new StringBuilder();
        while (i < m || j < n) {
            if (i < m) {
                ans.Append(word1[i]);
                ++i;
            }
            if (j < n) {
                ans.Append(word2[j]);
                ++j;
            }
        }
        return ans.ToString();
    }
}
1071. 字符串的最大公因子
1071. 字符串的最大公因子 - 力扣（LeetCode）
[!Note]
对于字符串 s 和 t，只有在 s = t + t + t + ... + t + t（t 自身连接 1 次或多次）时，我们才认定 “t 能除尽 s”。
给定两个字符串 str1 和 str2 。返回 最长字符串 x，要求满足 x 能除尽 str1 且 x 能除尽 str2 。
public class Solution {
    public bool judge(string str, string subStr)
    // 判断 str 是否能被 subStr 除尽
    {
        bool flag = true;
        int j = 0;
        // 如果从长度上不能除尽，直接排除
        if (str.Length % subStr.Length != 0)
        {
            flag = false;
        }
        else
        {
            for (int i = 0; i < str.Length; i++)
            {
                if (str[i] == subStr[j])
                {
                    j++;
                    if (j >= subStr.Length)
                    {
                        j = 0;
                    }
                }
                else
                {
                    flag = false;
                    break;
                }
            }
        }
        return flag;
    }
    public string GcdOfStrings(string str1, string str2) {
        // 寻求两个字符串的最大公共前缀
        string temp = "";
        int min = str1.Length < str2.Length ? str1.Length : str2.Length;
        for (int i = 0; i < min; i++) {
            if (str1[i] == str2[i]) {
                temp += str1[i];
            } else {
                break;
            }
        }
        // 逐一排除
        string x = "";
        string subStr = "";
        for(int i = 0; i < temp.Length; i++) {
            subStr = temp.Substring(0, temp.Length - i);
            if(judge(str1, subStr) && judge(str2, subStr)){
                x = subStr;
                break;
            }
        }
        return x;
    }
}
​	官方解：
public class Solution {
    public string GcdOfStrings(string str1, string str2) {
        // 如果他们有公因子那么他们 正反拼接都是一样的 都由公因子重复
        // 否则就不存在最大公约串
        if(str1 + str2 != str2 + str1)
        {
            return "";
        }   

        int gcd = GCD(str1.Length, str2.Length);
        return str1.Substring(0, gcd);
    }

    // 计算 a, b 的最大公约数，也就是计算两个字符串的长度的最大公约数
    private int GCD(int a ,int b)
    {
        return b == 0 ? a: GCD(b, a % b);
    }
}
1431. 拥有最多糖果的孩子
[!Note]
有 n 个有糖果的孩子。给你一个数组 candies，其中 candies[i] 代表第 i 个孩子拥有的糖果数目，和一个整数 extraCandies 表示你所有的额外糖果的数量。
返回一个长度为 n 的布尔数组 result，如果把所有的 extraCandies 给第 i 个孩子之后，他会拥有所有孩子中 最多 的糖果，那么 result[i] 为 true，否则为 false。
注意，允许有多个孩子同时拥有 最多 的糖果数目。
public class Solution {
    public IList<bool> KidsWithCandies(int[] candies, int extraCandies) {
        IList<bool> boolList = new List<bool>();
        // 找到最大值
        int max = candies[0];
        foreach (var x in candies) {
            if (x > max){
                max = x;
            }
        }
        // 判断是否有效
        foreach (var x in candies) {
            boolList.Add(x + extraCandies >= max);
        }
        return boolList;
    }
}
