helper.h（C 头文件，给 C++ 调用）
#ifndef HELPER_H
#define HELPER_H

#ifdef __cplusplus
extern "C" {  // 避免 C++ 名字修饰
#endif

int c_add(int a, int b);
int c_subtract(int a, int b);

#ifdef __cplusplus
}
#endif

