    void Update()
    {
        if (!GameObject.Find("Canvas").transform.Find("ScenesControllerUI"))
        {
            timer = enterSceneTime + waitTime;
            initUI();
            // enterScene = true;
        }
    }

    private void initUI()
    {
        Debug.Log("initUI()");
        UIGameObject = Instantiate(scenesControllerUIPrefab);
